from __future__ import annotations

import logging
from pathlib import Path, PurePosixPath
from typing import Any, Dict, Iterable, List, Optional, Tuple

from . import get_artifacts_root
from .filename_parsing import tokenize_filename
from .github_storage import is_github_location, list_github_artifacts
from .registry import LocationEntry, LocationNotFoundError, get_registry_entries, match_location
from . import storage
from .storage import (
    ArtifactNotFoundError,
    InvalidArtifactExtensionError,
    InvalidArtifactPathError,
)

logger = logging.getLogger(__name__)


def _enumerate_candidate_files() -> List[Tuple[str, LocationEntry, Path]]:
    root = get_artifacts_root()
    registry = get_registry_entries()
    candidates: List[Tuple[str, LocationEntry, Path]] = []
    seen: set[str] = set()

    # Enumerate local filesystem artifacts
    if root.exists():
        for path in root.rglob("*"):
            if not path.is_file():
                continue
            # Skip metadata override files - they are not artifacts themselves
            if path.name.endswith(".metadata.json"):
                continue
            rel = path.relative_to(root)
            artifact_id = rel.as_posix()
            if artifact_id in seen:
                continue
            seen.add(artifact_id)
            rel_posix = PurePosixPath(artifact_id)
            try:
                location_entry = match_location(list(rel_posix.parts))
            except LocationNotFoundError:
                continue
            suffix = path.suffix.lower()
            allowed = {e.lower() for e in location_entry.allowed_extensions}
            if suffix not in allowed:
                continue
            candidates.append((artifact_id, location_entry, path))

    # Enumerate GitHub-backed locations
    for location_key, location_entry in registry.items():
        if is_github_location(location_entry):
            try:
                logger.info("Enumerating GitHub location: %s", location_key)
                artifact_ids = list_github_artifacts(location_entry, location_key)
                for artifact_id in artifact_ids:
                    if artifact_id in seen:
                        continue
                    seen.add(artifact_id)
                    # GitHub artifacts don't have real filesystem paths during enumeration
                    # Use a placeholder - actual path resolution happens in get_artifact_metadata
                    placeholder_path = root / artifact_id
                    candidates.append((artifact_id, location_entry, placeholder_path))
            except Exception as e:
                logger.error("Failed to enumerate GitHub location %s: %s", location_key, e)

    return candidates


def search_artifacts(criteria: Dict[str, Any]) -> Dict[str, Any]:
    """Search artifacts using the elimination pipeline."""

    domains_filter = set(criteria.get("domains") or [])
    locations_filter = set(criteria.get("locations") or [])
    tags_filter = set(criteria.get("tags") or [])
    topics_filter = set(criteria.get("topics") or [])
    keywords_raw = criteria.get("keywords") or []
    keywords_filter = {str(k) for k in keywords_raw}
    limit_raw = criteria.get("limit", 50)
    offset_raw = criteria.get("offset", 0)
    try:
        limit = int(limit_raw)
        offset = int(offset_raw)
    except (TypeError, ValueError) as exc:
        raise InvalidArtifactPathError("limit and offset must be integers") from exc
    if limit <= 0:
        raise InvalidArtifactPathError("limit must be positive")
    if offset < 0:
        raise InvalidArtifactPathError("offset must be non-negative")
    candidates = _enumerate_candidate_files()
    total_candidates = len(candidates)
    after_domain_list: List[Tuple[str, LocationEntry, Path]] = []
    for artifact_id, location_entry, path in candidates:
        if domains_filter and location_entry.domain not in domains_filter:
            continue
        after_domain_list.append((artifact_id, location_entry, path))
    after_domain = len(after_domain_list)
    after_location_list: List[Tuple[str, LocationEntry, Path]] = []
    for artifact_id, location_entry, path in after_domain_list:
        if locations_filter:
            loc_key = location_entry.key
            matched = False
            for prefix in locations_filter:
                if loc_key == prefix or loc_key.startswith(prefix + "/"):
                    matched = True
                    break
            if not matched:
                continue
        after_location_list.append((artifact_id, location_entry, path))
    after_location = len(after_location_list)
    after_tags_topics_list: List[Tuple[str, LocationEntry, Path]] = []
    for artifact_id, location_entry, path in after_location_list:
        if tags_filter:
            if not tags_filter.issubset(set(location_entry.tags)):
                continue
        if topics_filter:
            if not topics_filter.issubset(set(location_entry.topics)):
                continue
        after_tags_topics_list.append((artifact_id, location_entry, path))
    after_tags_topics = len(after_tags_topics_list)
    surviving: List[Tuple[str, LocationEntry, Path]] = []
    for artifact_id, location_entry, path in after_tags_topics_list:
        if keywords_filter:
            rules_dict: Optional[Dict[str, Any]] = None
            if location_entry.filename_rules is not None:
                rules = location_entry.filename_rules
                rules_dict = {
                    "token_delimiters": rules.token_delimiters,
                    "case": rules.case,
                }
            tokens = tokenize_filename(path.name, rules=rules_dict)
            # Normalize both tokens and keywords based on location's case setting
            normalize_case = rules_dict.get("case", "lower") if rules_dict else "lower"
            if normalize_case == "lower":
                token_set = {t.lower() for t in tokens}
                normalized_keywords = {k.lower() for k in keywords_filter}
            else:
                token_set = set(tokens)
                normalized_keywords = keywords_filter
            if not normalized_keywords.issubset(token_set):
                continue
        surviving.append((artifact_id, location_entry, path))
    after_keywords = len(surviving)
    surviving.sort(
        key=lambda item: (
            item[1].domain,
            item[1].key,
            item[0],
            Path(item[0]).name,
        )
    )
    sliced = surviving[offset : offset + limit]
    results: List[Dict[str, Any]] = []
    for artifact_id, _location_entry, _path in sliced:
        try:
            metadata = storage.get_artifact_metadata(artifact_id)
        except (ArtifactNotFoundError, InvalidArtifactExtensionError) as exc:
            logger.warning("Skipping artifact %s during search: %s", artifact_id, exc)
            continue
        results.append(metadata)
    elimination_trace = {
        "total_candidates": total_candidates,
        "after_domain": after_domain,
        "after_location": after_location,
        "after_tags_topics": after_tags_topics,
        "after_keywords": after_keywords,
    }
    return {"results": results, "elimination_trace": elimination_trace}

def get_artifact_metadata(artifact_id: str) -> Dict[str, Any]:
    """Infer metadata for an artifact from its path and registry entry."""

    path = _artifact_path_from_id(artifact_id)
    if not path.is_file():
        raise ArtifactNotFoundError(f"Artifact not found at {artifact_id}")
    rel_path = PurePosixPath(artifact_id)
    try:
        location_entry = _infer_location_entry_for_relative_path(rel_path)
    except LocationNotFoundError as exc:
        raise InvalidArtifactPathError(str(exc)) from exc
    extension = Path(path.name).suffix
    _ = _validate_extension_for_location(path.name, location_entry)
    rules_dict: Optional[Dict[str, Any]] = None
    if location_entry.filename_rules is not None:
        rules = location_entry.filename_rules
        rules_dict = {
            "token_delimiters": rules.token_delimiters,
            "case": rules.case,
        }
    tokens = tokenize_filename(path.name, rules=rules_dict)
    pattern_defs = None
    if location_entry.filename_rules is not None:
        pattern_defs = [
            {"name": p.name, "regex": p.regex}
            for p in location_entry.filename_rules.patterns
        ]
    fields = extract_fields(path.name, patterns=pattern_defs)
    metadata: Dict[str, Any] = {
        "artifact_id": artifact_id,
        "path": rel_path.as_posix(),
        "domain": location_entry.domain,
        "location": location_entry.key,
        "tags": list(location_entry.tags),
        "topics": list(location_entry.topics),
        "filename": path.name,
        "extension": extension,
        "tokens": tokens,
        "fields": fields,
    }
    custom = _load_custom_metadata(path)
    if custom is not None:
        metadata["custom"] = custom
    return metadata


def list_artifacts(location_prefix: str) -> List[str]:
    """List all artifact IDs under a given location prefix."""

    # Reject absolute paths or paths that escape the root
    if location_prefix.startswith("/"):
        raise InvalidArtifactPathError("Location prefix must not be an absolute path")

    rel_prefix = PurePosixPath(location_prefix)
    if any(part in ("", ".", "..") for part in rel_prefix.parts):
        raise InvalidArtifactPathError("Location prefix contains invalid segments")

    root = get_artifacts_root()
    base = root.joinpath(*rel_prefix.parts)

    # Verify base is within the artifact root
    try:
        base.resolve().relative_to(root.resolve())
    except ValueError as exc:
        raise InvalidArtifactPathError("Location prefix escapes artifact root") from exc
    if not base.exists():
        return []
    artifact_ids: List[str] = []
    for path in base.rglob("*"):
        if not path.is_file():
            continue
        # Skip metadata override files - they are not artifacts themselves
        if path.name.endswith(".metadata.json"):
            continue
        rel = path.relative_to(root)
        rel_posix = rel.as_posix()
        try:
            location_entry = _infer_location_entry_for_relative_path(
                PurePosixPath(rel_posix)
            )
        except LocationNotFoundError:
            continue
        ext_lower = path.suffix.lower()
        allowed = {e.lower() for e in location_entry.allowed_extensions}
        if ext_lower not in allowed:
            continue
        artifact_ids.append(rel_posix)
    return artifact_ids

async def _fetch_content(
    self, results: list[tuple[str, ArtifactSearchResult]]
) -> list[ArtifactWithContent]:
    """Fetch content for each artifact from its source engine."""
    artifacts = []

    async def fetch_one(
        engine: str, result: ArtifactSearchResult
    ) -> Optional[ArtifactWithContent]:
        client = self.clients.get(engine)
        if not client:
            return None

        try:
            content = await client.get_content(result.artifact_id)
            tokens = self.count_tokens(content)
            title = self.infer_title(content, result.artifact_id)
            return ArtifactWithContent(
                artifact_id=result.artifact_id,
                engine=engine,
                content=content,
                tokens=tokens,
                title=title,
            )
        except Exception as e:
            logger.error(f"Failed to fetch {result.artifact_id}: {e}")
            return None

    if self.config.parallel_fetch:
        tasks = [fetch_one(engine, result) for engine, result in results]
        fetched = await asyncio.gather(*tasks)
        artifacts = [a for a in fetched if a is not None]
    else:
        for engine, result in results:
            a = await fetch_one(engine, result)
            if a is not None:
                artifacts.append(a)

    return artifacts

